do $$
declare n int; p int;
begin
  if encode(digest('RF-AUDIT-0002', 'sha256'), 'hex') <> '3fa2f61932166676478a2386b322491e68e35dd981a41c3c21b445e3a3a3fe46' then raise exception 'ABORTED: license_hash literal for RF-AUDIT-0002 is wrong. Nothing committed.'; end if;
  if not exists (select 1 from public.license_keys where key = 'RF-AUDIT-0002' and app_id = 'sairnroofing' and status = 'active') then raise exception 'ABORTED: RF-AUDIT-0002 is not an active sairnroofing licence. Nothing committed.'; end if;
  select count(*) into n from public.sairnroofing_employee_auth where license_hash = '3fa2f61932166676478a2386b322491e68e35dd981a41c3c21b445e3a3a3fe46';
  select count(*) into p from public.sairnroofing_employee_auth where license_hash = '3fa2f61932166676478a2386b322491e68e35dd981a41c3c21b445e3a3a3fe46' and active and role = any (array['owner']);
